    private class P(val d: String, val alpha: Float, val evenOdd: Boolean)

    private fun p(d: String, alpha: Float = 1f, evenOdd: Boolean = false) = P(d, alpha, evenOdd)

    private fun icon(vararg paths: P): ImageVector =
        ImageVector.Builder(
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f,
        ).apply {
            for (path in paths) {
                addPath(
                    pathData = addPathNodes(path.d),
                    pathFillType = if (path.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                    fill = SolidColor(Color.Black),
                    fillAlpha = path.alpha,
                )
            }
        }.build()
}
